# -*- coding: utf-8 -*-
# Обновление системного промта kip8 до post-Task 312+313+314
# (ПЕРЕНОС ПАРТИИ Tasks 312-314 из kip8test@894afab одним инкрементом
#  SW kipia-v416→v417): «+ Отпуск» в карточку + чистый попап ячейки
#  (Task 312), подсветка «сегодня» + окно «Мероприятия в этот день»
#  (Task 313), «·» с фоном пустой ячейки + бейджи мероприятий +
#  локальная копия графика + кнопка «Обновить» (Task 314).
with open('Системный_промт_для_приложения_КИПиА.md', encoding='utf-8') as f:
    lines = f.readlines()

new3 = '''> **Версия документа:** 2026-09-04 (post-Task 314: ПЕРЕНОС ПАРТИИ Tasks 312-314 из kip8test@894afab в боевой kip8 ОДНИМ инкрементом SW kipia-v416→v417 — заявки пользователя: Task 312 «В разделе "График работы", в баре над шахматкой убери кнопку "+ Отпуск", а её функционал перемести в новую кнопку в окно сотрудника в блок отпуска. В открывающимся окне ячеек шахматки коды, которые добавляются через "+ Мероприятия", убери из списка основных… убери самый первый код… "— выходной"»; Task 313 «В шахматке должен немного подсвечиваться фон сегодняшней даты. При нажатии на ячейку… должно появляться ещё одно отдельное окно, расположенное над окном с кодами… "Мероприятия в этот день"»; Task 314 «Замени символ кода "." на символ "·", а цвет фона ячейки сделай как в пустых, и напиши код цвета — заменю в таблице. Мероприятия из таблицы "Инструктажи" должны отображаться в ячейках шахматки маленькими бейджами-«иконками». Сделай, чтобы последняя загруженная информация по графику работы сохранялась локально… график открывался моментально без ожидания подгрузки… обновление данных графика… с помощью кнопки обновления данных графика (не формирования)». СОДЕРЖАНИЕ ПАРТИИ: 1) TASK 312 — кнопка «+ Отпуск» УДАЛЕНА из тулбара (wsVacBtn/ws-addvac-btn, CSS обеих тем, управление видимостью в init) — вместо неё строка-действие «+ Отпуск…» (.ws-popup-row.ws-popup-more.ws-emp-addvac) в блоке «Отпуска · год» КАРТОЧКИ сотрудника (только _canEdit; onEmpAddVacation → openVacationForm с префиллом таб.№: часть и лимит 42 сразу для нужного сотрудника); попап ячейки: строка «— выходной —» УДАЛЕНА (кода «—» нет; очистка — select «Дополнительно…»), коды мероприятий (И/ОБ/ПЗ/ПР/*) ИСКЛЮЧЕНЫ из списка основных (_EVENT_CODES; только бейджи в ячейках и «+ Мероприятие…»; select шита: не предлагаются, текущее значение живо); fallback-цвет «.» #CFD8DC→#FAF9F5. 2) TASK 313 — подсветка сегодняшней даты: th.ws-today-col (градиент поверх непрозрачного фона + акцентное число) и td.ws-today (inset-«заливка» поверх inline-цветов статусов; составное правило «сегодня+ручная» — две inset-тени), тёмная/светлая темы, видна зрителям; ОТДЕЛЬНОЕ окно #wsEventsPopup (z-9402) «Мероприятия в этот день» НАД окном кодов при клике по ячейке (_renderEventsPopup: заголовок + «дата · ФИО», строки цвет/код/название, ✎/✕ редакторам, «нет мероприятий»; левые края выровнены, зазор 8px, окно кодов сдвигается вниз; closeCellPopup закрывает оба); секция «Мероприятия в этот день» из окна кодов УДАЛЕНА. 3) TASK 314 — «.» рендерится как ПУСТАЯ ячейка: символ «·» (U+00B7), CSS-класс ws-dot-code (тёмная var(--bg-primary)/светлая #eef0f2 = фон ячеек; inline-цвет листа НЕ применяется; ЦВЕТ ДЛЯ ЛИСТА: #EEF0F2 — сообщён пользователю); showMainCode = статус И НЕ «.» И НЕ мероприятие; мероприятия «Инструктажи» — бейджи-«иконки» ГЛАВНАЯ форма: статус-мероприятие БЕЗ большого кода (ячейка «·» + СПЛОШНОЙ бейдж; нет записи — виртуальный бейдж), бейджи ВИДНЫ на днях отсутствия (сплошные) и пустых/планах (ПУНКТИРНЫЕ), смена — код + мини-бейдж; ЛОКАЛЬНАЯ КОПИЯ графика: localStorage kip8_ws_cache_v1 (справочники + отпуска по годам + записи/мероприятия по видам «год-месяц», лимит 12; _restoreCachedView → мгновенный рендер БЕЗ сети; _cacheWrite после каждой загрузки, loadGrid(true) ×11 у мутаций; штамп «данные от …») + НОВАЯ кнопка #wsRefreshBtn «Обновить» (ВСЕМ ролям; refreshData = тихие коды + loadGrid(true) + тост + спиннер; НЕ «Сформировать»; сетка не мигает, сбой не стирает; офлайн-толерантность). СЕРВЕР/листы/Apps Script НЕ менялись; значение «.» в данных остаётся «.». ПЕРЕНОС: патч index.html 1388 строк (git apply, чисто; изоляционный дифф 55 строк не тронут); sw.js kipia-v416→v417; tests/ — НОВЫЕ test-task312.js/test-task313.js/test-task314.js (адаптация версий v550/v551/v552→v416, v553→v417) + 14 файлов копии с адаптацией + run-all.js +3 require; Тесты: 1511 → 1584/0 (ПАРИТЕТ с kip8test@894afab); 4 script-блока node --check OK. Верификация: task312-browser-check.py 31/31, task313-browser-check.py 30/30, task314-browser-check.py 36/36 на РЕАЛЬНОМ kip8/index.html (порты 8938/8939/8940) + регресс task307 20/20, task308 20/20, task309 26/26, task310 20/20, task311 24/24 (актуализированы под партию); VLM ×4. Деплой пользователя: GitHub Pages + Ctrl+Shift+R ×1–2 (SW v417); Apps Script/листы НЕ трогать; в листе «Коды_статусов» заменить цвет «.» на #EEF0F2; kip8-desktop — автосинк.)
'''

assert lines[2].startswith('> **Версия документа:**')
lines.insert(2, new3 if new3.endswith('\n') else new3 + '\n')
prev = [i for i, l in enumerate(lines[:40]) if l.startswith('> **Версия документа (предыдущая):**')]
while len(prev) > 12:
    del lines[prev[-1]]
    prev = [i for i, l in enumerate(lines[:40]) if l.startswith('> **Версия документа (предыдущая):**')]
print('Строка 3 вставлена; цепочка «предыдущих»:', len(prev))

src = ''.join(lines)

reps = [
    # Версия кэша в шапке (была неактуальна v414 — доводим до v417)
    ('> **Текущая версия кэша:** `kipia-v414`',
     '> **Текущая версия кэша:** `kipia-v417`'),
    # Таблица репозиториев
    ('| `kip8` | PWA + APK | `kipia-v414` |',
     '| `kip8` | PWA + APK | `kipia-v417` |'),
    ('| `kip8test` | PWA | `kipia-test-v539` |',
     '| `kip8test` | PWA | `kipia-test-v553` |'),
    # Пример CACHE_VERSION
    ('`CACHE_VERSION` (например, `kipia-v414`)',
     '`CACHE_VERSION` (например, `kipia-v417`)'),
    # Счётчики фронтенда
    ('весь код в одном `index.html` (~39.9 тыс. строк, ~2.4 MB)',
     'весь код в одном `index.html` (~40.5 тыс. строк, ~2.4 MB)'),
    ('| Тесты | Node.js + кастомный фреймворк (`tests/`, 1476 теста, `node tests/run-all.js`) |',
     '| Тесты | Node.js + кастомный фреймворк (`tests/`, 1584 теста, 32 тест-файла, `node tests/run-all.js`) |'),
    # Последняя принятая партия
    ('> **Последняя принятая партия:** Tasks 298-311',
     '> **Последняя принятая партия:** Tasks 298-314'),
]
for old, new in reps:
    n = src.count(old)
    assert n == 1, (old, n)
    src = src.replace(old, new)
print('Версии/счётчики обновлены (%d замен)' % len(reps))

# Маркер конца партии в строке «Последняя принятая партия» (дата задачи 311 → 314)
old_party = 'Tests 298-311'
src = src  # (строка уже заменена выше)

# Буллет переноса в журнал переносов (после «Перенос Task 311: …»)
entry = ('- **Перенос Task 312+313+314 (партия, kip8test@894afab → kip8, один инкремент SW kipia-v416→v417, сервер/листы не менялись):** '
         '1) «+ Отпуск» из тулбара — строкой в блок отпусков карточки сотрудника (префилл таб.№, только редакторам); попап ячейки без «— выходной —» и без кодов мероприятий в списке основных; '
         '2) подсветка столбца сегодняшней даты (шапка+ячейки, поверх inline-цветов) + отдельное окно «Мероприятия в этот день» НАД окном кодов при клике по ячейке (секция из окна кодов удалена); '
         '3) «.» → символ «·» на фоне ПУСТОЙ ячейки (код для листа #EEF0F2, inline-цвет не применяется); мероприятия «Инструктажи» — маленькие бейджи во всех ячейках (сплошные на сформированных/отсутствиях, пунктирные на пустых/планах); локальная копия графика (kip8_ws_cache_v1) — мгновенное открытие без сети + кнопка «Обновить» (всем ролям, спиннер/тост/штамп «данные от …», сбой не стирает сетку). '
         'Верификация: патч 1388 строк чисто, тесты 1511→1584/0 (паритет), browser 312=31/31, 313=30/30, 314=36/36 + регресс 307-311 = 20/20/26/20/24, VLM ×4. Деплой: GitHub Pages + Ctrl+Shift+R ×1–2 (SW v417); Apps Script/листы не трогать; цвет «.» в «Коды_статусов» → #EEF0F2; kip8-desktop — автосинк. См. scripts/DEPLOY-Task312-vac-in-card-popup-clean.md, DEPLOY-Task313-today-highlight-events-window.md, DEPLOY-Task314-dot-badges-cache.md')
anchor = '- **Перенос Task 311: карточка зачищена, hover-окна убраны, «+ Сотрудник» → заголовок «С'
i = src.find(anchor)
assert i != -1, 'якорь журнала переносов не найден'
j = src.find('\n', i)
src = src[:j+1] + entry + '\n' + src[j+1:]
print('Буллет переноса добавлен в журнал')

with open('Системный_промт_для_приложения_КИПиА.md', 'w', encoding='utf-8') as f:
    f.write(src)
print('Промт kip8 обновлён до post-Task 312+313+314 (перенос партии)')
